// Federation worker enqueues outgoing envelopes
await valkey.xadd('fed:outgoing:alice-dev-01', '*', {
  envelope_id: 'env_abc123',
  target: 'did:cell:bob-dev-02',
  payload: JSON.stringify(envelope),
  status: 'pending',
  created_at: Date.now()
});

// Consumer group processes delivery
const results = await valkey.xreadgroup(
  'GROUP', 'fed-workers', 'worker-1',
  'COUNT', 1,
  'BLOCK', 5000,
  'STREAMS', 'fed:outgoing:alice-dev-01', '>'
);
